-- WalletLedger V1
-- All UUIDs are generated by the Java application and stored as BINARY(16).
-- DATETIME(6) values are maintained in UTC.

CREATE TABLE users (
    id BINARY(16) NOT NULL,
    name VARCHAR(100) NOT NULL,
    email VARCHAR(254) NOT NULL,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),

    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT uq_users_email UNIQUE (email)
) ENGINE = InnoDB
  DEFAULT CHARACTER SET = utf8mb4
  COLLATE = utf8mb4_0900_ai_ci;


CREATE TABLE wallets (
    id BINARY(16) NOT NULL,
    user_id BINARY(16) NOT NULL,
    wallet_type VARCHAR(10) NOT NULL,
    currency CHAR(3) NOT NULL DEFAULT 'INR',
    balance BIGINT NOT NULL DEFAULT 0,
    version BIGINT NOT NULL DEFAULT 0,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
        ON UPDATE CURRENT_TIMESTAMP(6),

    -- A SYSTEM wallet produces 1; USER wallets produce NULL.
    -- MySQL permits multiple NULL values in a UNIQUE index.
    system_wallet_guard TINYINT
        GENERATED ALWAYS AS (
            CASE WHEN wallet_type = 'SYSTEM' THEN 1 ELSE NULL END
        ) STORED,

    CONSTRAINT pk_wallets PRIMARY KEY (id),

    CONSTRAINT uq_wallets_user_currency
        UNIQUE (user_id, currency),

    CONSTRAINT uq_wallets_one_system
        UNIQUE (system_wallet_guard),

    CONSTRAINT fk_wallets_user
        FOREIGN KEY (user_id) REFERENCES users (id),

    CONSTRAINT chk_wallets_type
        CHECK (wallet_type IN ('USER', 'SYSTEM')),

    CONSTRAINT chk_wallets_currency
        CHECK (currency = 'INR'),

    CONSTRAINT chk_wallets_balance
        CHECK (wallet_type = 'SYSTEM' OR balance >= 0),

    CONSTRAINT chk_wallets_version
        CHECK (version >= 0)

) ENGINE = InnoDB
  DEFAULT CHARACTER SET = utf8mb4
  COLLATE = utf8mb4_0900_ai_ci;
-- Transactions and idempotency
CREATE TABLE transactions (
    id BINARY(16) NOT NULL,
    type VARCHAR(16) NOT NULL,
    status VARCHAR(16) NOT NULL DEFAULT 'PENDING',

    idempotency_key VARCHAR(128)
        CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    request_hash BINARY(32) NOT NULL,

    amount BIGINT NOT NULL,
    initiated_by BINARY(16) NOT NULL,
    source_wallet_id BINARY(16) NOT NULL,
    destination_wallet_id BINARY(16) NOT NULL,
    original_txn_id BINARY(16) NULL,

    response_status SMALLINT UNSIGNED NULL,
    response_body JSON NULL,

    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
        ON UPDATE CURRENT_TIMESTAMP(6),

    -- A non-failed reversal reserves its original transaction.
    -- FAILED reversals produce NULL, freeing the unique slot.
    reversed_original_guard BINARY(16)
        GENERATED ALWAYS AS (
            CASE
                WHEN type = 'REVERSAL' AND status <> 'FAILED'
                THEN original_txn_id
                ELSE NULL
            END
        ) STORED,

    CONSTRAINT pk_transactions PRIMARY KEY (id),

    -- Idempotency keys are unique per caller, not globally.
    CONSTRAINT uq_transactions_caller_idempotency
        UNIQUE (initiated_by, idempotency_key),

    -- Only one non-failed reversal may reference each original.
    CONSTRAINT uq_transactions_reversal_once
        UNIQUE (reversed_original_guard),

    CONSTRAINT fk_transactions_initiated_by
        FOREIGN KEY (initiated_by) REFERENCES users (id),

    CONSTRAINT fk_transactions_source_wallet
        FOREIGN KEY (source_wallet_id) REFERENCES wallets (id),

    CONSTRAINT fk_transactions_destination_wallet
        FOREIGN KEY (destination_wallet_id) REFERENCES wallets (id),

    CONSTRAINT fk_transactions_original
        FOREIGN KEY (original_txn_id) REFERENCES transactions (id),

    CONSTRAINT chk_transactions_type
        CHECK (type IN ('TOPUP', 'TRANSFER', 'WITHDRAWAL', 'REVERSAL')),

    CONSTRAINT chk_transactions_status
        CHECK (status IN ('PENDING', 'COMPLETED', 'FAILED', 'REVERSED')),

    CONSTRAINT chk_transactions_amount
        CHECK (amount > 0),

    CONSTRAINT chk_transactions_different_wallets
        CHECK (source_wallet_id <> destination_wallet_id),

    CONSTRAINT chk_transactions_reversal_link
        CHECK (
            (type = 'REVERSAL' AND original_txn_id IS NOT NULL)
            OR
            (type <> 'REVERSAL' AND original_txn_id IS NULL)
        ),

    CONSTRAINT chk_transactions_response_status
        CHECK (
            response_status IS NULL
            OR response_status BETWEEN 100 AND 599
        )

) ENGINE = InnoDB
  DEFAULT CHARACTER SET = utf8mb4
  COLLATE = utf8mb4_0900_ai_ci;

-- Append-only double-entry ledger
CREATE TABLE ledger_entries (
    id BIGINT NOT NULL AUTO_INCREMENT,
    transaction_id BINARY(16) NOT NULL,
    wallet_id BINARY(16) NOT NULL,
    direction VARCHAR(6) NOT NULL,
    amount BIGINT NOT NULL,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),

    CONSTRAINT pk_ledger_entries PRIMARY KEY (id),

    CONSTRAINT fk_ledger_entries_transaction
        FOREIGN KEY (transaction_id) REFERENCES transactions (id),

    CONSTRAINT fk_ledger_entries_wallet
        FOREIGN KEY (wallet_id) REFERENCES wallets (id),

    -- At most one debit and one credit per wallet per transaction.
    CONSTRAINT uq_ledger_transaction_wallet_direction
        UNIQUE (transaction_id, wallet_id, direction),

    CONSTRAINT chk_ledger_direction
        CHECK (direction IN ('DEBIT', 'CREDIT')),

    CONSTRAINT chk_ledger_amount
        CHECK (amount > 0),

    INDEX idx_ledger_wallet_cursor (wallet_id, id DESC)

) ENGINE = InnoDB;

-- Append-only transaction state-change audit trail
CREATE TABLE transaction_audit (
    id BIGINT NOT NULL AUTO_INCREMENT,
    transaction_id BINARY(16) NOT NULL,
    from_status VARCHAR(16) NULL,
    to_status VARCHAR(16) NOT NULL,
    changed_by BINARY(16) NULL,
    reason VARCHAR(255) NULL,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),

    CONSTRAINT pk_transaction_audit PRIMARY KEY (id),

    CONSTRAINT fk_transaction_audit_transaction
        FOREIGN KEY (transaction_id) REFERENCES transactions (id),

    CONSTRAINT fk_transaction_audit_user
        FOREIGN KEY (changed_by) REFERENCES users (id),

    CONSTRAINT chk_transaction_audit_from_status
        CHECK (
            from_status IS NULL
            OR from_status IN ('PENDING', 'COMPLETED', 'FAILED', 'REVERSED')
        ),

    CONSTRAINT chk_transaction_audit_to_status
        CHECK (
            to_status IN ('PENDING', 'COMPLETED', 'FAILED', 'REVERSED')
        ),

    INDEX idx_transaction_audit_history (transaction_id, id DESC)

) ENGINE = InnoDB;

-- Transactional outbox: events are committed with the business transaction.
CREATE TABLE outbox_events (
    id BIGINT NOT NULL AUTO_INCREMENT,
    aggregate_type VARCHAR(50) NOT NULL,
    aggregate_id BINARY(16) NOT NULL,
    event_type VARCHAR(100) NOT NULL,
    payload JSON NOT NULL,
    published BOOLEAN NOT NULL DEFAULT FALSE,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    published_at DATETIME(6) NULL,

    CONSTRAINT pk_outbox_events PRIMARY KEY (id),

    CONSTRAINT chk_outbox_published_timestamp
        CHECK (
            (published = FALSE AND published_at IS NULL)
            OR
            (published = TRUE AND published_at IS NOT NULL)
        ),

    INDEX idx_outbox_unpublished (published, id)

) ENGINE = InnoDB;

-- Append-only protections for the financial ledger.
-- Simple, single-statement triggers: no DELIMITER directive is needed.
CREATE TRIGGER trg_ledger_entries_no_update
BEFORE UPDATE ON ledger_entries
FOR EACH ROW
SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'ledger_entries is append-only';

CREATE TRIGGER trg_ledger_entries_no_delete
BEFORE DELETE ON ledger_entries
FOR EACH ROW
SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'ledger_entries is append-only';


-- Append-only protections for the transaction audit trail.
CREATE TRIGGER trg_transaction_audit_no_update
BEFORE UPDATE ON transaction_audit
FOR EACH ROW
SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'transaction_audit is append-only';

CREATE TRIGGER trg_transaction_audit_no_delete
BEFORE DELETE ON transaction_audit
FOR EACH ROW
SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'transaction_audit is append-only';
